lifecycle.insecure:
// identity read from a forgeable token
const persona = atob(token).split(':')[1];
return dataFor(persona);

lifecycle.secure:
// opaque random id -> server-side session record
const sess = await sessions.get(token);          // 128-bit random id
if (!sess) return res.sendStatus(401);
// rotate on login, invalidate on logout, set HttpOnly+Secure+SameSite
return dataFor(sess.userId);
